import{_ as r,c as a,o,a7 as e}from"./chunks/framework.DPTpzYjp.js";const s="/ruidu-docs/images/orbitcontrol/user-guide/auth-page-login.png",i="/ruidu-docs/images/orbitcontrol/user-guide/auth-page-register.png",n="/ruidu-docs/images/orbitcontrol/user-guide/tenant-page-guide.png",l="/ruidu-docs/images/orbitcontrol/user-guide/tenant-page-new.png",b=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/quick-start.md","filePath":"orbitcontrol/user-guide/quick-start.md"}'),d={name:"orbitcontrol/user-guide/quick-start.md"};function g(p,t,c,u,h,m){return o(),a("div",null,t[0]||(t[0]=[e('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>本章带你从零开始完成账号注册、进入企业，直到第一次操控设备。</p><h2 id="注册账号" tabindex="-1">注册账号 <a class="header-anchor" href="#注册账号" aria-label="Permalink to &quot;注册账号&quot;">​</a></h2><p>打开平台地址，进入登录页，点击「立即注册」。</p><p><img src="'+s+'" alt="" class="w-1/2"></p><p>填写用户名、邮箱和密码完成注册。用户名用于登录系统，密码至少 6 个字符。</p><p><img src="'+i+'" alt="" class="w-1/2"></p><h2 id="进入企业" tabindex="-1">进入企业 <a class="header-anchor" href="#进入企业" aria-label="Permalink to &quot;进入企业&quot;">​</a></h2><p>平台以<strong>企业</strong>为隔离单位：站点、设备、任务等资源都属于某个企业，用户必须加入企业后才能使用平台功能。</p><p>注册成功后登录，如果账号尚未加入任何企业，平台会自动进入「开始使用」向导：</p><ul><li><strong>创建新企业</strong>：适合第一个使用平台的用户，创建后自动成为该企业的<strong>所有者</strong></li><li><strong>加入现有企业</strong>：请联系企业管理员获取<strong>邀请码</strong>，在「申请加入企业」页面输入 8 位邀请码并提交，等待管理员审核通过</li></ul><p><img src="'+n+'" alt=""></p><p>创建新企业时需要填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>企业名称</td><td>企业的显示名称，例如：睿度智能科技</td></tr><tr><td>企业代码</td><td>企业唯一标识，小写字母、数字、连字符和下划线，<strong>创建后不可修改</strong></td></tr></tbody></table><p><img src="'+l+'" alt=""></p><h2 id="首次配置" tabindex="-1">首次配置 <a class="header-anchor" href="#首次配置" aria-label="Permalink to &quot;首次配置&quot;">​</a></h2><p>进入平台后，按以下顺序完成基础配置，之后就可以开始操控设备了：</p><ol><li><strong>新建站点</strong> — 圈定设备的工作范围，参见 <a href="./sites.html">站点管理</a></li><li><strong>注册设备</strong> — 将设备接入平台并分配到站点，参见 <a href="./devices.html">设备管理</a></li><li><strong>建立地图</strong> — 遥控设备建图或导入已有地图，参见 <a href="./maps.html">地图管理</a></li><li><strong>绘制路网</strong>（可选）— 规划设备的行驶路网，参见 <a href="./route-graph.html">路网</a></li><li><strong>编排任务</strong> — 创建路径任务或网格任务，参见 <a href="./missions.html">任务</a></li></ol><p>配置完成后，进入「实况 → 设备控制」即可开始操控，参见 <a href="./live-control.html">设备控制</a>。</p>',19)]))}const f=r(d,[["render",g]]);export{b as __pageData,f as default};
